<style>
.seller-dashboard{--sd-surface:#fff;--sd-tint:#f5f9f6;--sd-border:#dfe8e2;--sd-ink:#233e31;--sd-muted:#687d70;--sd-green:#1f6f5b;min-width:0;color:var(--sd-ink);font-size:13px;line-height:1.6}.seller-dashboard *{box-sizing:border-box;min-width:0}.seller-dashboard :is(h2,h3,p){margin:0;overflow-wrap:anywhere}.seller-dashboard :is(a,button,summary,circle):focus-visible{outline:3px solid #75b499;outline-offset:3px}.seller-dashboard a{text-decoration:none}.sd-intro{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:22px}.sd-intro h2{font-size:25px;font-weight:600;letter-spacing:-.6px}.sd-intro p,.sd-panel-heading p{color:var(--sd-muted);font-size:12px}.sd-eyebrow{display:block;font-size:10px;text-transform:uppercase;letter-spacing:.12em;font-weight:600;color:var(--sd-green);margin-bottom:3px}.sd-timezone{font-size:11px;color:var(--sd-muted);border:1px solid var(--sd-border);padding:7px 12px;border-radius:20px;white-space:nowrap}.sd-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px;margin-bottom:20px}.sd-kpi,.sd-panel{background:var(--sd-surface);border:1px solid var(--sd-border);border-radius:18px;box-shadow:0 3px 16px #173f3505}.sd-kpi{padding:20px;color:var(--sd-ink);transition:border-color .15s}.sd-kpi:hover{border-color:#81b69d}.sd-kpi>div{display:flex;justify-content:space-between;align-items:center;gap:10px}.sd-kpi i,.sd-kpi svg{width:20px;height:20px;color:var(--sd-green)}.sd-kpi-label{font-size:12px;color:var(--sd-muted)}.sd-kpi>strong{display:block;font-size:clamp(20px,2.1vw,29px);font-weight:600;letter-spacing:-.7px;margin:9px 0;overflow-wrap:anywhere}.sd-kpi p{font-size:10px;color:var(--sd-muted);display:flex;justify-content:space-between;gap:6px}.sd-analytics,.sd-operations{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(270px,1fr);gap:20px;margin-bottom:20px}.sd-panel{min-width:0;overflow:hidden}.sd-panel-heading{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:20px 22px;border-bottom:1px solid var(--sd-border)}.sd-panel-heading h3{font-size:15px;font-weight:600}.sd-panel-heading a{color:var(--sd-green);font-size:11px;font-weight:600;white-space:nowrap}.sd-chart-toolbar{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap;padding:20px 22px 5px}.sd-chart-toolbar strong{font-size:27px;font-weight:600;letter-spacing:-.6px}.sd-chart-toolbar p{font-size:10px;color:var(--sd-muted)}.sd-range-controls{display:flex;flex-wrap:wrap;gap:4px;background:var(--sd-tint);border:1px solid var(--sd-border);border-radius:10px;padding:4px}.sd-range-controls button{font:inherit;font-size:10px;padding:7px 9px;border:0;border-radius:7px;background:transparent;color:var(--sd-muted);cursor:pointer}.sd-range-controls button[aria-pressed=true]{color:white;background:var(--sd-green)}.sd-chart-wrap{padding:4px 14px 0}.sd-sales-chart{display:block;width:100%;height:auto;overflow:visible}.sd-chart-grid path{fill:none;stroke:var(--sd-border);stroke-dasharray:4 5}.sd-chart-line{fill:none;stroke:#1f6f5b;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}.sd-chart-axis{font-size:10px;fill:var(--sd-muted)}[data-sales-points] circle{fill:var(--sd-surface);stroke:#1f6f5b;stroke-width:2;cursor:crosshair}[data-sales-points] circle:hover,[data-sales-points] circle:focus{fill:#1f6f5b;stroke:#a7dac1;stroke-width:4}.sd-chart-detail{margin:0 22px!important;padding:8px 12px;border-radius:8px;background:var(--sd-tint);font-size:11px;min-height:34px}.sd-chart-empty{padding:0 22px 10px;color:var(--sd-muted);font-size:12px}.sd-chart-empty[hidden]{display:none}.sd-data-table{margin:12px 22px;font-size:11px}.sd-data-table summary{cursor:pointer;color:var(--sd-green);font-weight:600}.sd-data-table table{width:100%;border-collapse:collapse;margin-top:10px}.sd-data-table :is(th,td){padding:6px;text-align:left;border-bottom:1px solid var(--sd-border)}.sd-data-table caption{text-align:left;color:var(--sd-muted);padding:4px}.sd-note{padding:12px 22px 18px;font-size:10px;color:var(--sd-muted)}.sd-status-body{padding:20px}.sd-status-visual{position:relative;width:min(100%,210px);margin:0 auto 16px}.sd-status-donut{display:block;width:100%;height:auto;overflow:visible}.sd-status-track{stroke:var(--sd-border)}.sd-status-segment{stroke:var(--status-color);cursor:pointer;transition:opacity .15s,stroke-width .15s;pointer-events:stroke}.sd-status-segment.is-highlighted{stroke-width:27}.sd-status-segment.is-dimmed{opacity:.28}.sd-status-segment:focus-visible{outline:none;filter:drop-shadow(0 0 2px var(--sd-ink));stroke-width:27}.sd-status-center{position:absolute;inset:29%;display:flex;flex-direction:column;align-items:center;justify-content:center;pointer-events:none}.sd-status-center strong{font-size:32px;line-height:1.2;font-weight:600}.sd-status-center span{font-size:10px;color:var(--sd-muted)}.sd-status-insight{min-height:55px;padding:10px 12px;border:1px solid var(--sd-border);border-radius:10px;background:var(--sd-tint);font-size:11px;color:var(--sd-muted);margin-bottom:16px!important}.sd-status-insight.has-selection{border-left:4px solid var(--status-color);color:var(--sd-ink)}.sd-status-legend{list-style:none;margin:0;padding:0;display:grid;gap:7px}.sd-status-legend li{border:1px solid var(--sd-border);border-radius:10px;overflow:hidden}.sd-status-choice{display:grid;grid-template-columns:8px minmax(0,1fr) auto auto;align-items:center;gap:9px;width:100%;padding:11px 10px;background:transparent;border:0;color:var(--sd-ink);font:inherit;font-size:11px;text-align:left;cursor:pointer;min-height:44px}.sd-status-choice:hover,.sd-status-choice[aria-pressed=true]{background:var(--sd-tint)}.sd-status-choice[aria-pressed=true]{box-shadow:inset 3px 0 var(--status-color)}.sd-status-choice strong{color:color-mix(in srgb,var(--status-color),black 20%);font-size:14px}.sd-status-choice small{font-size:10px;color:var(--sd-muted);font-variant-numeric:tabular-nums}.sd-status-legend .is-zero .sd-status-choice{color:var(--sd-muted)}.sd-status-legend .is-zero strong{font-weight:400}.sd-status-dot{display:inline-block;width:8px;height:8px;border-radius:50%;flex:none;background:var(--status-color)}.sd-status-orders-link{display:block;font-size:10px;color:var(--sd-green);padding:0 10px 8px 27px}.sd-status-details{margin-top:18px;border-top:1px solid var(--sd-border);padding-top:14px;font-size:11px}.sd-status-details summary{cursor:pointer;color:var(--sd-green);font-weight:600;min-height:30px}.sd-status-details>p{color:var(--sd-muted);font-size:10px;margin-top:5px!important}.sd-status-details>div{display:flex;flex-wrap:wrap;gap:7px;margin-top:10px}.sd-status-badge{display:inline-flex;align-items:center;gap:6px;background:var(--sd-tint);color:var(--sd-ink);border:1px solid var(--sd-border);border-left:3px solid var(--status-color);padding:6px 8px;border-radius:7px;overflow-wrap:anywhere}.sd-status-badge strong{color:color-mix(in srgb,var(--status-color),black 20%)}
html[data-theme=dark] .seller-dashboard :is(.sd-status-choice strong,.sd-status-badge strong){color:color-mix(in srgb,var(--status-color),white 48%)}
@media(prefers-reduced-motion:reduce){.seller-dashboard .sd-status-segment{transition:none}}.sd-finances{margin-bottom:20px}.sd-financial-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));padding:18px 22px;gap:20px}.sd-financial-grid p{font-size:11px;color:var(--sd-muted)}.sd-financial-grid strong{display:block;font-size:20px;color:var(--sd-ink);font-weight:600;margin:6px 0;overflow-wrap:anywhere}.sd-financial-grid small{font-size:10px;color:var(--sd-muted);display:block}.sd-operations{grid-template-columns:minmax(0,1fr) minmax(0,1.4fr)}.sd-quick-actions{display:grid;padding:10px 20px}.sd-quick-actions a{display:flex;align-items:center;gap:12px;padding:15px 0;border-bottom:1px solid var(--sd-border);color:var(--sd-ink)}.sd-quick-actions a:last-child{border:0}.sd-quick-actions svg{width:19px;height:19px;color:var(--sd-green);flex:none}.sd-quick-actions strong{display:block;font-size:12px}.sd-quick-actions small{display:block;font-size:10px;color:var(--sd-muted)}.sd-quick-actions a>span:last-child{margin-left:auto;color:var(--sd-green)}.sd-stock-row{display:flex;gap:12px;padding:16px 22px;border-bottom:1px solid var(--sd-border)}.sd-stock-row:last-child{border:0}.sd-stock-image{position:relative;flex:0 0 42px;height:42px;display:grid;place-items:center;background:var(--sd-tint);border-radius:10px;overflow:hidden}.sd-stock-image img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:var(--sd-surface)}.sd-stock-image img[hidden]{display:none}.sd-stock-image svg{width:18px;height:18px;color:var(--sd-muted)}.sd-stock-row>div{flex:1}.sd-stock-row a{font-weight:600;color:var(--sd-ink);overflow-wrap:anywhere}.sd-stock-row p{font-size:10px;color:var(--sd-muted)}.sd-stock-row ul{padding:0;list-style:none;margin:5px 0 0;display:grid;gap:5px}.sd-stock-row li{display:flex;justify-content:space-between;gap:10px;font-size:10px;overflow-wrap:anywhere}.sd-stock-badge{font-size:9px;border-radius:20px;background:#fff3d7;color:#855712;padding:2px 7px;white-space:nowrap}.sd-stock-badge.is-out{background:#ffe8e2;color:#a14531}.sd-table-scroll{overflow-x:auto;max-width:100%}.sd-orders{width:100%;border-collapse:collapse;min-width:650px;text-align:left}.sd-orders th{font-size:9px;text-transform:uppercase;letter-spacing:.06em;background:var(--sd-tint);color:var(--sd-muted);font-weight:600;padding:12px 18px;white-space:nowrap}.sd-orders td{padding:16px 18px;font-size:11px;border-top:1px solid var(--sd-border);vertical-align:middle}.sd-orders td:first-child{max-width:230px}.sd-orders td strong{display:block;font-size:11px;overflow-wrap:anywhere}.sd-orders td small{display:block;font-size:10px;color:var(--sd-muted);overflow-wrap:anywhere;margin-top:3px}.sd-orders td a{font-weight:600;color:var(--sd-green);white-space:nowrap}.sd-order-status{display:inline-block;padding:4px 8px;background:var(--sd-tint);border:1px solid var(--sd-border);border-radius:20px;font-size:9px;white-space:nowrap}.status-completed,.status-delivered{background:#e5f4eb;color:#246746;border-color:#c8e4d4}.status-cancelled,.status-delivery_failed,.status-rts_completed{background:#fff0e7;color:#9d5130;border-color:#f0d7c9}.sd-top-products{margin-top:20px}.sd-top-products ol{margin:0;list-style:decimal;padding:4px 22px 10px 42px}.sd-top-products li{padding:12px 0;border-bottom:1px solid var(--sd-border);font-size:12px}.sd-top-products li:last-child{border:0}.sd-top-products li span{display:block;font-size:10px;color:var(--sd-muted)}.sd-empty{padding:25px 22px!important;font-size:12px;color:var(--sd-muted)}.sd-feedback{padding:12px;background:#e5f4eb;border-radius:10px;margin-bottom:15px!important}.sd-feedback.sd-error{background:#fff0e7;color:#9d5130}
html[data-theme=dark] .seller-dashboard{--sd-surface:#19271f;--sd-tint:#203229;--sd-border:#354c3e;--sd-ink:#e0ece4;--sd-muted:#a9beb0;--sd-green:#a2d8bd}html[data-theme=dark] .seller-dashboard .sd-kpi{color:var(--sd-ink)}html[data-theme=dark] .seller-dashboard .sd-range-controls button[aria-pressed=true]{background:#2f7759;color:white}html[data-theme=dark] .seller-dashboard .sd-chart-line{stroke:#7fc6a5}html[data-theme=dark] .seller-dashboard [data-sales-points] circle{stroke:#7fc6a5}html[data-theme=dark] .seller-dashboard :is(.sd-intro,.sd-panel-heading){background:var(--sd-surface)}
@media(max-width:1100px){.sd-kpis,.sd-financial-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.sd-analytics{grid-template-columns:minmax(0,1fr)}}@media(max-width:700px){.sd-operations{grid-template-columns:minmax(0,1fr)}.sd-intro{align-items:flex-start;flex-direction:column}.sd-intro h2{font-size:22px}.sd-kpis{gap:10px}.sd-kpi{padding:15px}.sd-panel-heading{padding:17px}.sd-chart-toolbar{padding:15px 17px}.sd-status-ring{width:150px;height:150px}.sd-status-ring>div{width:110px;height:110px}.sd-financial-grid{padding:16px;gap:15px}.sd-kpi>strong{font-size:21px}.sd-sales-chart{min-height:180px}}@media(max-width:390px){.sd-kpis{grid-template-columns:minmax(0,1fr)}}@media(prefers-reduced-motion:reduce){.sd-kpi{transition:none}}
</style>
